 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join pairs of 1 markers lying on a 45-degree diagonal.
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i+1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                cells = []
                r, c = r1, c1
                while True:
                    cells.append((r, c))
                    if (r, c) == (r2, c2):
                        break
                    r += dr; c += dc
                segments.append((cells, dr, dc))
                for r, c in cells:
                    out[r][c] = 1

    # A 6 on a joined 1 diagonal marks the crossing and sends a 6 diagonal
    # perpendicular to that segment, extending to the grid boundaries.
    for cells, dr, dc in segments:
        for r, c in sixes:
            if (r, c) in cells:
                for sr, sc in ((dr, -dc), (-dr, dc)):
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 6
                        rr += sr; cc += sc
                    rr, cc = r - sr, c - sc
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 6
                        rr -= sr; cc -= sc
    return out
